package synk

import (
	"path"
	"strings"
	"time"
)

// isReplacementSiblingName recognizes names generated by
// replacementSiblingName without classifying ordinary lookalike files.
func isReplacementSiblingName(name string) bool {
	base := path.Base(name)
	marker := strings.LastIndex(base, ".icloud-synk-")
	if marker < 0 {
		return false
	}

	remainder := base[marker+len(".icloud-synk-"):]
	kind, stamp, ok := strings.Cut(remainder, "-")
	if !ok || (kind != "new" && kind != "backup" && kind != "failed") {
		return false
	}

	if len(stamp) < 25 {
		return false
	}

	timestamp := stamp[:25]
	parsed, err := time.Parse("20060102T150405.000000000", timestamp)
	if err != nil || parsed.Format("20060102T150405.000000000") != timestamp {
		return false
	}

	suffix := stamp[25:]
	return suffix == "" || (strings.HasPrefix(suffix, ".") && len(suffix) > 1)
}
